<script lang="ts">
 import type {AppData} from '#lib/client/types.ts';
 import {sourceHref} from '#lib/client/source-links.ts';
  import type {Row} from '#lib/client/types.ts';
  import {display} from '#lib/client/api.ts';
  import {reportList,reportMoney,reportNumber} from '#lib/client/reports.ts';
  import Icon from '../Icon.svelte';
  import ReportComparison from './ReportComparison.svelte';
  let {data,rows,currency,canWrite=false}:{data:AppData;rows:Row[];currency?:string;canWrite?:boolean}=$props();
  const costLabels:Record<string,string>={material:'Materialverbrauch',labor:'Freigegebene Arbeit',external:'Direkte Fremdleistung',machine:'Maschinen',transport:'Transport',other:'Weitere direkte Kosten'};
  const fields=[{key:'ordered_net',label:'Bestätigter Auftragswert netto'},{key:'planned_costs',label:'Ursprünglich geplante Kosten'},{key:'direct_actual_costs',label:'Direkte Istkosten'},{key:'committed_remaining_costs',label:'Noch nicht verbrauchte Verpflichtungen'},{key:'uncommitted_remaining_costs',label:'Zusätzlich geschätzte Restkosten'},{key:'etc',label:'Erwartete gesamte Restkosten (ETC)'},{key:'eac',label:'Erwartete Gesamtkosten (EAC)'},{key:'expected_contribution',label:'Erwarteter direkter Deckungsbeitrag'}];
</script>
<section class="panel"><header class="panel-header"><div><h2>Auftragskosten & verbleibender Aufwand</h2><p>Istkosten, noch gebundene Kosten und bestätigte Restschätzungen bleiben getrennt.</p></div>{#if canWrite}<a class="btn small" href={sourceHref(data,'/cost-estimates')}>Restschätzungen pflegen<Icon name="arrow" size={14}/></a>{/if}</header>
  <div class="panel-body cost-intro"><p class="small">Der direkte Deckungsbeitrag ist der bestätigte Auftragswert abzüglich erwarteter direkter Gesamtkosten. Gemeinkosten und Betriebsergebnis sind darin nicht enthalten.</p></div>
  {#each rows as order}
    {@const unit=order.currency||currency}
    <details class="cost-order"><summary><div><h3>{order.order_number||'Auftrag'} · {order.title||'Kostenstand'}</h3><p>Restschätzung {order.estimate_version?'Version '+order.estimate_version:'noch nicht bestätigt'}{order.estimate_date?' · Stand '+display(order.estimate_date,'date'):''}</p></div><div class="cost-summary"><span>Erwartete Gesamtkosten</span><strong>{reportMoney(order.eac,unit)}</strong></div><Icon name="chevron" size={18}/></summary><div class="cost-expanded"><dl class="definition-list">{#each fields as field}<div><dt>{field.label}</dt><dd class:cost-negative={field.key==='expected_contribution'&&reportNumber(order[field.key])!==null&&Number(order[field.key])<0}>{reportMoney(order[field.key],unit)}</dd></div>{/each}<div class="full"><dt>Bewertungsgrundlage / Annahmen</dt><dd>{order.basis||order.estimate_basis||'Für diesen Stand ist noch keine bestätigte Restschätzung hinterlegt.'}</dd></div></dl>
    <div class="mt"><ReportComparison rows={[{label:'Direkte Kosten des Auftrags',planned:order.planned_costs,actual:order.direct_actual_costs,remaining:order.etc}]} fields={[{key:'planned',label:'Plan',color:'#a6b39b'},{key:'actual',label:'Ist',color:'#4b7252'},{key:'remaining',label:'Rest',color:'#b29160'}]} currency={unit} monetary caption="Plan, Ist und erwarteter Rest im Vergleich"/></div>
    {#if reportList(order.by_type).length}<div class="table-scroll mt"><table class="data-table"><caption class="sr-only">Kostenarten des Auftrags {order.order_number||order.title}</caption><thead><tr><th>Kostenart</th><th class="number">Plan</th><th class="number">Ist</th><th class="number">Rest</th></tr></thead><tbody>{#each reportList(order.by_type) as type}<tr><th scope="row">{type.label||costLabels[type.kind||type.cost_type]||'Direkte Kosten'}</th><td class="number">{reportMoney(type.planned_costs??type.plan,unit)}</td><td class="number">{reportMoney(type.direct_actual_costs??type.actual,unit)}</td><td class="number">{reportMoney(type.etc??type.remaining,unit)}</td></tr>{/each}</tbody></table></div>{/if}
    {#if reportList(order.issues).length}<ul class="cost-issues">{#each reportList(order.issues) as issue}<li>{typeof issue==='string'?issue:issue.message||issue.label||issue.title}</li>{/each}</ul>{/if}
    <div class="inline-actions mt"><a class="btn" href={sourceHref(data,`/orders/${order.order_id}`)}>Auftrag und Ursprungsbelege<Icon name="arrow" size={15}/></a>{#if canWrite}<a class="btn" href={sourceHref(data,`/cost-estimates?order_id=${order.order_id}`)}>Restschätzung prüfen</a><a class="text-link" href={sourceHref(data,`/performance-valuations?order_id=${order.order_id}`)}>Leistungsbewertung prüfen<Icon name="arrow" size={14}/></a>{/if}</div></div></details>
  {/each}
  {#if !rows.length}<div class="empty-state compact"><Icon name="briefcase" size={27}/><h3>Noch kein belastbarer Auftragskostenstand</h3><p>Auftragsbezogene Verbräuche, freigegebene Arbeitszeiten und bestätigte Restschätzungen werden hier gemeinsam nachvollziehbar.</p>{#if canWrite}<a class="btn" href={sourceHref(data,'/cost-estimates')}>Erste Restschätzung vorbereiten</a>{/if}</div>{/if}
</section>
<style>.cost-intro{border-bottom:1px solid var(--line)}.cost-order{border-bottom:1px solid var(--line)}.cost-order:last-child{border-bottom:0}.cost-order>summary{display:flex;align-items:center;gap:20px;padding:23px 24px;cursor:pointer;list-style:none}.cost-order>summary::-webkit-details-marker{display:none}.cost-order>summary>div:first-child{flex:1;min-width:0}.cost-order h3{font-size:14px;font-weight:550;line-height:1.5}.cost-order p{font-size:12px;margin-top:5px}.cost-summary{display:grid;gap:5px;text-align:right}.cost-summary span{font-size:11px;color:var(--muted)}.cost-summary strong{font-size:16px;font-weight:550;font-variant-numeric:tabular-nums}.cost-expanded{padding:0 24px 25px}.cost-expanded dd{font-variant-numeric:tabular-nums}.cost-negative{color:var(--danger);font-weight:600}.cost-issues{margin:20px 0 0;padding-left:18px;font-size:12px;color:var(--warning)}.cost-issues li+li{margin-top:7px}@media(max-width:760px){.cost-order>summary{padding:21px 20px;gap:15px;flex-wrap:wrap}.cost-order>summary>div:first-child{flex-basis:calc(100% - 40px)}.cost-order>summary>.cost-summary{flex-basis:100%;order:3;text-align:left}.cost-order h3{font-size:15px}.cost-summary span{font-size:12px}.cost-expanded{padding:0 20px 24px}.cost-issues{font-size:13px}.panel-header{flex-wrap:wrap}}</style>
